import sqlite3, json
from collections import defaultdict

STEPS = ["install", "tutorial_complete", "first_match", "purchase"]

con = sqlite3.connect("analytics.db")
users = {u: (p, t) for u, p, t in con.execute("select user_id, platform, is_test from users")}

# events grouped per user, filtered per rules: drop test accounts and unknown players
events = defaultdict(lambda: defaultdict(list))
orphan_users = set()
for u, name, ts in con.execute("select user_id, name, ts from events"):
    if u not in users:
        orphan_users.add(u)
        continue
    if users[u][1]:
        continue  # test account
    if name in STEPS:
        events[u][name].append(ts)

platforms = defaultdict(lambda: {s: 0 for s in STEPS})
for u, (platform, _test) in users.items():
    evs = events.get(u, {})
    prev = None
    for s in STEPS:
        ts_list = sorted(t for t in evs.get(s, []) if prev is None or t >= prev)
        if not ts_list:
            break
        prev = ts_list[0]  # first valid occurrence
        platforms[platform][s] += 1

result = {
    "funnel": {p: {s: c[s] for s in STEPS} for p, c in platforms.items()},
    "biggest_drop": {},
}
for p, c in platforms.items():
    best_step, best_rate = None, None
    for i in range(1, len(STEPS)):
        prev_n, cur_n = c[STEPS[i-1]], c[STEPS[i]]
        rate = cur_n / prev_n if prev_n else 1.0
        if best_rate is None or rate < best_rate:
            best_step, best_rate = STEPS[i], rate
    result["biggest_drop"][p] = {
        "step": best_step,
        "conversion": round(best_rate, 4),
        "from_step": STEPS[STEPS.index(best_step) - 1],
        "players_lost": c[STEPS[STEPS.index(best_step) - 1]] - c[best_step],
    }

print(json.dumps(result, indent=2))
print("orphan event users:", len(orphan_users), "| test users:", sum(1 for x in users.values() if x[1]))
with open("result.json", "w") as f:
    json.dump(result, f, indent=2)


